"use client";

import { useEffect, useMemo, useState } from "react";
import { Link } from "@tanstack/react-router";
import { Area, Bar, BarChart, CartesianGrid, Cell, ComposedChart, Line, XAxis, YAxis } from "recharts";
import type { MoneyTrackerPageData } from "../src/protected-data.js";
import { moneyFinancialHistory, moneyFinancialPosition, moneyTrackerTrendStats, type MoneyFinancialPosition, type MoneyTrackerAccountCategory, type MoneyTrackerTrendStats } from "./money-tracker-domain.js";
import { AppShell } from "../src/components/app-shell.js";
import { Alert, AlertDescription, AlertTitle } from "../src/components/ui/alert.js";
import { Badge } from "../src/components/ui/badge.js";
import { Button } from "../src/components/ui/button.js";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "../src/components/ui/card.js";
import { ChartContainer, ChartTooltip, ChartTooltipContent, type ChartConfig } from "../src/components/ui/chart.js";
import { compareMoneyValues, MoneySortableHead, MoneyTableSearch, nextMoneySort, type MoneySort } from "./money-data-table.js";
import { MoneyCategoryExplorer } from "./money-category-explorer.js";
import type { MoneyCategory } from "./money-enums.js";
import { MoneyActivityView, MoneyBalanceEntry, MoneyDataView, MoneyInvestmentsView, MoneyPlanningCard, MoneySpendingView } from "./money-ledger-views.js";
import { MoneyNav, moneyViewTitle, type MoneyTrackerView } from "./money-tracker-navigation.js";

export type { MoneyTrackerView } from "./money-tracker-navigation.js";
type Period = "6m" | "1y" | "all";
type Month = MoneyTrackerPageData["months"][number];
type GroupedMonth = Month & { money: number; stocks: number; trend: number; observed?: boolean; portfolioDate?: string };

const currency = new Intl.NumberFormat("de-DE", { style: "currency", currency: "EUR", maximumFractionDigits: 0 });
const preciseCurrency = new Intl.NumberFormat("de-DE", { style: "currency", currency: "EUR" });
const colors = ["#67e8f9", "#c084fc", "#facc15", "#4ade80", "#60a5fa", "#fb7185", "#f472b6"];
// Colors are passed directly to Recharts. ChartConfig colors generate an inline
// style element, which the platform's nonce-only CSP intentionally blocks.
const totalConfig = { money: { label: "Cash" }, stocks: { label: "Portfolio value" }, total: { label: "Known net worth" }, trend: { label: "Linear trend" } } satisfies ChartConfig;
const changeConfig = { change: { label: "Balance change" } } satisfies ChartConfig;

export function MoneyTrackerPage(props: MoneyTrackerPageData & { view: MoneyTrackerView; category?: MoneyCategory }) {
  const [period, setPeriod] = useState<Period>("1y");
  const cashAccounts = useMemo(() => props.accounts.filter((account) => roleCategory(props.accountRoles, account) === "money"), [props.accountRoles, props.accounts]);
  const balanceAccounts = useMemo(() => props.accounts.filter((account) => props.accountLastObserved[account] !== undefined), [props.accountLastObserved, props.accounts]);
  const allCashMonths = useMemo(() => props.months.map((month) => cashMonth(month, cashAccounts)), [cashAccounts, props.months]);
  const allMonths = useMemo(() => {
    const financial = moneyFinancialHistory(allCashMonths.map((month) => ({ date: month.date, cashValue: month.money, ...cashCoverage(month, cashAccounts) })), props.marketData.history);
    return financial.map((point, index) => ({ ...allCashMonths[index]!, ...point, trend: point.total }));
  }, [allCashMonths, cashAccounts.length, props.marketData.history]);
  const months = useMemo(() => withLinearTrend(period === "all" ? allMonths : allMonths.slice(period === "6m" ? -6 : -12)), [allMonths, period]);
  const allAccountMonths = useMemo(() => props.months.map((month) => groupMonth(month, props.accountRoles)), [props.accountRoles, props.months]);
  const visibleAccountMonths = useMemo(() => period === "all" ? allAccountMonths : allAccountMonths.slice(period === "6m" ? -6 : -12), [allAccountMonths, period]);
  const latest = months.at(-1);
  const previous = months.at(-2);
  const latestCash = allCashMonths.at(-1);
  const position = useMemo(() => moneyFinancialPosition({ asOf: props.marketData.asOf, cashValueMinor: Math.round((latestCash?.money ?? 0) * 100), cashObservationDate: latestCash?.date, ...cashCoverage(latestCash, cashAccounts), marketData: props.marketData }), [cashAccounts, latestCash, props.marketData]);
  const latestObservedChange = withChanges(months).at(-1);
  const monthlyChange = latestObservedChange && latestObservedChange.date === latest?.date ? latestObservedChange.change : undefined;
  const trends = useMemo(() => moneyTrackerTrendStats(months, allMonths), [allMonths, months]);
  const showPeriod = props.view === "accounts" || props.view === "insights";

  return <><AppShell product="Money" accent="lime" showSignOut /><main id="main" className="app-page money-page">
    <header className="app-heading mb-0">
      <div><p className="eyebrow">Money</p><h1>{moneyViewTitle(props.view)}</h1><p>{viewDescription(props.view)}</p></div>
      {showPeriod ? <div className="app-heading__actions"><PeriodSelector period={period} onPeriod={setPeriod} /></div> : null}
    </header>
    <div className="money-layout">
      <MoneyNav />
      <div className="money-content space-y-4">
        {props.view === "overview" ? <Overview {...props} position={position} months={months} latest={latest} trends={trends} period={period} onPeriod={setPeriod} /> : null}
        {props.view === "transactions" ? <MoneyActivityView activity={props.activity} accounts={props.accounts} accountLabels={props.accountLabels} transactionCount={props.transactionCount} revertedCount={props.revertedCount} spending={props.spending} transferReview={props.transferReview} transferReviewGroups={props.transferReviewGroups} /> : null}
        {props.view === "cash-flow" ? <MoneySpendingView spending={props.spending} /> : null}
        {props.view === "categories" ? <MoneyCategoryExplorer spending={props.spending} initialCategory={props.category} /> : null}
        {props.view === "investments" ? <MoneyInvestmentsView investments={props.investments} marketData={props.marketData} /> : null}
        {props.view === "accounts" ? <><Accounts accounts={props.accounts} accountLabels={props.accountLabels} accountRoles={props.accountRoles} accountLastObserved={props.accountLastObserved} months={visibleAccountMonths} latest={visibleAccountMonths.at(-1)} previous={visibleAccountMonths.at(-2)} /><History accounts={balanceAccounts} accountLabels={props.accountLabels} months={visibleAccountMonths} /><MoneyBalanceEntry accounts={cashAccounts} accountLabels={props.accountLabels} /></> : null}
        {props.view === "insights" ? <Insights {...props} accounts={cashAccounts} position={position} months={months} latest={latest} previous={previous} monthlyChange={monthlyChange} trends={trends} /> : null}
        {props.view === "data" ? <MoneyDataView {...props} /> : null}
      </div>
    </div>
  </main></>;
}

function Overview({ accounts, marketData, revertedCount, spending, transferReview, position, months, latest, trends, period, onPeriod }: MoneyTrackerPageData & { position: MoneyFinancialPosition; months: GroupedMonth[]; latest?: GroupedMonth; trends: MoneyTrackerTrendStats; period: Period; onPeriod: (period: Period) => void }) {
  const observedCashFlow = spending.months.filter((month) => month.observed);
  const recentCashFlow = observedCashFlow.slice(-6);
  const maximumCashFlow = Math.max(...recentCashFlow.flatMap((month) => [month.spendMinor, month.incomeMinor]), 1);
  const lastCashFlow = observedCashFlow.at(-1);
  const savingsRate = lastCashFlow?.incomeMinor ? lastCashFlow.netCashFlowMinor / lastCashFlow.incomeMinor * 100 : undefined;
  const unresolvedTransfers = transferReview.unresolvedPositiveCount + transferReview.unresolvedNegativeCount;
  const observedAccounts = position.cash.observedAccountCount;
  const carriedAccounts = position.cash.carriedAccountCount;
  const unpricedPositions = marketData.positions.filter((position) => position.state === "unpriced").length;
  const stalePositions = marketData.positions.filter((position) => position.state === "stale").length;
  const attentionCount = Number(spending.uncategorizedCount > 0) + Number(unresolvedTransfers > 0) + Number(unpricedPositions + stalePositions > 0) + Number(carriedAccounts > 0);
  return <>
    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4" aria-label="Money summary">
      <Metric label="Known net worth" value={formatMinor(position.knownNetWorthMinor, "EUR")} detail={`${formatSigned(trends.periodChange?.change)} selected range · ${carriedAccounts ? `${carriedAccounts} carried` : "cash observed"} · ${unpricedPositions ? `${unpricedPositions} unpriced` : stalePositions ? `${stalePositions} stale` : "prices current"}`} tone={tone(trends.periodChange?.change)} />
      <Metric label="Last cash-flow month" value={lastCashFlow ? formatMinor(lastCashFlow.netCashFlowMinor, "EUR") : "No data"} detail={savingsRate === undefined ? lastCashFlow?.month : `${lastCashFlow?.month} · ${savingsRate.toFixed(1)}% savings rate`} tone={tone(lastCashFlow?.netCashFlowMinor)} />
      <Metric label="Tracked cash" value={formatMinor(position.cash.valueMinor, "EUR")} detail={`${observedAccounts} observed, ${carriedAccounts} carried · ${position.cash.observationDate ?? "no snapshot"}`} />
      <Metric label="Portfolio value" value={formatMinor(position.portfolio.knownValueMinor, "EUR")} detail={`${formatMinor(marketData.totals.knownUnrealizedGainMinor, "EUR")} unrealized · ${marketData.positions.length - stalePositions - unpricedPositions} / ${marketData.positions.length} fresh`} tone={tone(marketData.totals.knownUnrealizedGainMinor)} />
    </section>
    <section className="grid items-start gap-3 lg:grid-cols-[minmax(0,1.7fr)_minmax(18rem,.7fr)]">
      <BalanceChart months={months} period={period} onPeriod={onPeriod} />
      <Card><CardHeader className="border-b"><div className="flex items-center justify-between gap-3"><div><CardTitle>Needs attention</CardTitle><CardDescription>Items that affect confidence in the totals</CardDescription></div><Badge variant={attentionCount ? "destructive" : "outline"}>{attentionCount} issue types</Badge></div></CardHeader><CardContent className="divide-y p-0">
        <AttentionRow label="Carried balances" value={carriedAccounts.toLocaleString("en-GB")} detail="Check when each account was last observed" ready={carriedAccounts === 0} view="accounts" action="Open accounts" />
        <AttentionRow label="Uncategorized spending" value={spending.uncategorizedCount.toLocaleString("en-GB")} detail="Complete categories for trustworthy spending" ready={spending.uncategorizedCount === 0} view="transactions" action="Review transactions" />
        <AttentionRow label="Unresolved transfer rows" value={unresolvedTransfers.toLocaleString("en-GB")} detail="Classify exact transaction groups before trusting cash flow" ready={unresolvedTransfers === 0} view="transactions" action="Review transfers" />
        <AttentionRow label="Portfolio valuation" value={marketData.positions.length ? unpricedPositions ? `${unpricedPositions} unpriced` : stalePositions ? `${stalePositions} stale` : "Current" : "No positions"} detail={marketData.positions.length ? `${marketData.positions.length - stalePositions - unpricedPositions} of ${marketData.positions.length} fresh` : "Import investment activity to begin"} ready={unpricedPositions + stalePositions === 0} view="investments" action="Open investments" />
        <p className="px-4 py-3 text-xs text-muted-foreground">{revertedCount.toLocaleString("en-GB")} reverted source rows are excluded from analytics.</p>
      </CardContent></Card>
    </section>
    <section className="grid items-start gap-3 lg:grid-cols-2">
      <Card><CardHeader className="border-b"><CardTitle>Recent cash flow</CardTitle><CardDescription>Months with imported activity, linked internal transfers excluded</CardDescription></CardHeader><CardContent className="space-y-3 pt-5">{recentCashFlow.length ? recentCashFlow.map((month) => <div className="grid grid-cols-1 items-center gap-2 text-xs sm:grid-cols-[4.5rem_minmax(5rem,1fr)_minmax(5rem,1fr)_6rem] sm:gap-3" key={month.month}><span className="text-muted-foreground">{month.month}</span><CashFlowBar label="Income" value={month.incomeMinor} maximum={maximumCashFlow} tone="income" /><CashFlowBar label="Spent" value={month.spendMinor} maximum={maximumCashFlow} tone="spend" /><div className="text-right"><span className="block text-muted-foreground">Net</span><strong className={`font-mono ${changeClass(month.netCashFlowMinor)}`}>{formatMinor(month.netCashFlowMinor, "EUR")}</strong></div></div>) : <p className="text-sm text-muted-foreground">Import a cash statement to see monthly cash flow.</p>}</CardContent></Card>
      <CashFlowReconciliation month={lastCashFlow} />
    </section>
  </>;
}

function CashFlowReconciliation({ month }: { month?: MoneyTrackerPageData["spending"]["months"][number] }) {
  return <Card><CardHeader className="border-b"><CardTitle>Cash-flow reconciliation</CardTitle><CardDescription>{month ? `${month.month} · every cash-flow component` : "No observed cash-flow month"}</CardDescription></CardHeader><CardContent className="divide-y p-0">{month ? <><StatRow label="Income" value={formatMinor(month.incomeMinor, "EUR")} /><StatRow label="Refunds" value={formatMinor(month.refundsMinor, "EUR")} /><StatRow label="Spending" value={`−${formatMinor(month.spendMinor, "EUR")}`} /><StatRow label="Fees" value={`−${formatMinor(month.feesMinor, "EUR")}`} /><StatRow label="Taxes" value={`−${formatMinor(month.taxesMinor, "EUR")}`} /><StatRow label="Net cash flow" value={formatMinor(month.netCashFlowMinor, "EUR")} detail="income + refunds − spending − fees − taxes" /></> : <p className="p-4 text-sm text-muted-foreground">Import cash activity to see the reconciliation.</p>}</CardContent></Card>;
}

function Insights({ accounts, accountLabels, accountRoles: providedAccountRoles, planning, position, months, latest, previous, monthlyChange, trends }: MoneyTrackerPageData & { position: MoneyFinancialPosition; months: GroupedMonth[]; latest?: GroupedMonth; previous?: GroupedMonth; monthlyChange?: number; trends: MoneyTrackerTrendStats }) {
  const accountRoles = { ...providedAccountRoles, __portfolio: "investment" as const };
  const changes = withChanges(months);
  const portfolioContributor = position.portfolio.openPositionCount || latest?.stocks ? [{ account: "__portfolio", label: "Portfolio", value: latest?.stocks, previous: previous?.stocks, change: latest && previous ? latest.stocks - previous.stocks : undefined }] : [];
  const contributors = [...accountRows(accounts, accountLabels, latest, previous), ...portfolioContributor].filter((item) => item.change !== undefined).sort((a, b) => Math.abs(b.change ?? 0) - Math.abs(a.change ?? 0));
  const maxChange = Math.max(...contributors.map((item) => Math.abs(item.change ?? 0)), 1);
  const composition = [...accountRows(accounts, accountLabels, latest), ...portfolioContributor].filter((item) => item.value !== undefined).sort((a, b) => (b.value ?? 0) - (a.value ?? 0));
  const topTwoShare = latest?.total ? composition.slice(0, 2).reduce((sum, item) => sum + (item.value ?? 0), 0) / latest.total * 100 : undefined;
  return <>
    <section className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6" aria-label="Balance summary"><Metric label="Known net worth" value={formatMinor(position.knownNetWorthMinor, "EUR")} detail={formatTrendPercent(trends.yearOverYear?.total.percent)} tone={tone(trends.yearOverYear?.total.change)} /><Metric label="Tracked cash" value={formatMinor(position.cash.valueMinor, "EUR")} detail={trends.yearOverYear ? `${formatSigned(trends.yearOverYear.money.change)} YoY` : position.cash.observationDate} tone={tone(trends.yearOverYear?.money.change)} /><Metric label="Portfolio value" value={formatMinor(position.portfolio.knownValueMinor, "EUR")} detail={`${position.portfolio.pricedPositionCount} / ${position.portfolio.openPositionCount} priced`} />{trends.drawdown ? <Metric label="Balance drawdown" value={formatTrendPercent(trends.drawdown.percent)} detail={formatSigned(trends.drawdown.change)} tone={tone(trends.drawdown.change)} /> : null}{trends.momentum ? <Metric label="3m average balance shift" value={formatTrendPercent(trends.momentum.percent)} detail={formatSigned(trends.momentum.change)} tone={tone(trends.momentum.change)} /> : null}<Metric label="Positive months" value={`${trends.positiveMonths.positive} / ${trends.positiveMonths.total}`} detail={formatTrendPercent(trends.positiveMonths.rate)} /></section>
    <MoneyPlanningCard planning={planning} />
    <section className="grid items-start gap-3 lg:grid-cols-[minmax(0,1.75fr)_minmax(18rem,.75fr)]">
      <ChartCard title="Tracked total and trend" description="Actual monthly total with a separate linear trend"><MountedChart fallback={<ChartFallback values={months.map((month) => month.total)} />}><ChartContainer config={totalConfig} className="h-[23rem] w-full aspect-auto" initialDimension={{ width: 760, height: 368 }} role="img" aria-label="Tracked total, cash and reported investment balances with linear trend. Exact values follow in an expandable table."><ComposedChart accessibilityLayer={false} data={months} margin={{ left: 4, right: 12, top: 8 }}><defs><linearGradient id="money-balance-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor={colors[0]} stopOpacity={0.34} /><stop offset="95%" stopColor={colors[0]} stopOpacity={0.04} /></linearGradient><linearGradient id="stock-balance-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor={colors[1]} stopOpacity={0.34} /><stop offset="95%" stopColor={colors[1]} stopOpacity={0.04} /></linearGradient></defs><CartesianGrid vertical={false} /><XAxis dataKey="date" tickLine={false} axisLine={false} tickMargin={10} minTickGap={28} /><YAxis tickLine={false} axisLine={false} width={72} tickFormatter={(value: number) => currency.format(value)} /><ChartTooltip content={<ChartTooltipContent />} /><Area dataKey="money" name="Cash" type="monotone" stackId="tracked" fill="url(#money-balance-fill)" stroke={colors[0]} strokeWidth={1.5} /><Area dataKey="stocks" name="Investment balances" type="monotone" stackId="tracked" fill="url(#stock-balance-fill)" stroke={colors[1]} strokeWidth={1.5} /><Line dataKey="total" name="Tracked total" type="monotone" stroke="#fafafa" strokeWidth={2.5} dot={false} /><Line dataKey="trend" name="Linear trend" type="linear" stroke="#facc15" strokeWidth={1.5} strokeDasharray="7 6" dot={false} /></ComposedChart></ChartContainer></MountedChart><BalanceDataDisclosure months={months} includeTrend /></ChartCard>
      <Card><CardHeader className="border-b"><CardTitle>Composition and concentration</CardTitle><CardDescription>{latest?.date ?? "No snapshot available"}</CardDescription></CardHeader><CardContent className="p-0"><div className="space-y-2 border-b px-4 py-4"><div className="flex justify-between text-xs"><span className="text-cyan-300">Cash {latest?.total ? `${(latest.money / latest.total * 100).toFixed(1)}%` : "—"}</span><span className="text-purple-300">Stocks {latest?.total ? `${(latest.stocks / latest.total * 100).toFixed(1)}%` : "—"}</span></div><div className="flex h-2 overflow-hidden rounded-full bg-muted"><div className="bg-cyan-300" style={{ width: `${latest?.total ? latest.money / latest.total * 100 : 0}%` }} /><div className="bg-purple-400" style={{ width: `${latest?.total ? latest.stocks / latest.total * 100 : 0}%` }} /></div><div className="divide-y">{composition.slice(0, 4).map((item) => <div className="grid grid-cols-[minmax(0,1fr)_auto] gap-3 py-2.5 text-sm" key={item.account}><div className="min-w-0"><p className="truncate font-medium">{item.label}</p><p className="text-xs text-muted-foreground">{roleCategory(accountRoles, item.account) === "stocks" ? "Stocks" : "Cash"}</p></div><div className="text-right font-mono"><p>{preciseCurrency.format(item.value ?? 0)}</p><p className="text-xs text-muted-foreground">{latest?.total ? `${((item.value ?? 0) / latest.total * 100).toFixed(1)}%` : "—"}</p></div></div>)}</div></div><div className="px-4 py-3 text-xs text-muted-foreground">{topTwoShare === undefined ? "No concentration data." : `The two largest accounts hold ${topTwoShare.toFixed(1)}% of the current total.`}</div></CardContent></Card>
    </section>
    <section className="grid gap-3 lg:grid-cols-2">
      <ChartCard title="Monthly balance change" description="Absolute month-over-month movement"><MountedChart fallback={<ChartFallback values={changes.map((month) => month.change)} />}><ChartContainer config={changeConfig} className="h-64 w-full aspect-auto" role="img" aria-label="Month-over-month tracked balance changes. Exact values follow in an expandable table."><BarChart accessibilityLayer={false} data={changes}><CartesianGrid vertical={false} /><XAxis dataKey="date" tickLine={false} axisLine={false} minTickGap={24} /><YAxis tickLine={false} axisLine={false} width={68} tickFormatter={(value: number) => currency.format(value)} /><ChartTooltip content={<ChartTooltipContent formatter={(value) => <TooltipValue label="Change" value={formatSigned(Number(value))} />} />} /><Bar dataKey="change" radius={3}>{changes.map((month) => <Cell key={month.date} fill={month.change < 0 ? "#fb7185" : "#4ade80"} />)}</Bar></BarChart></ChartContainer></MountedChart><ChangeDataDisclosure changes={changes} /></ChartCard>
      <Card><CardHeader className="border-b"><CardTitle>What moved this month</CardTitle><CardDescription>{formatSigned(monthlyChange)} across the latest snapshot</CardDescription></CardHeader><CardContent className="p-0">{(["stocks", "money"] as const).map((category) => { const items = contributors.filter((item) => roleCategory(accountRoles, item.account) === category); const subtotal = items.reduce((sum, item) => sum + (item.change ?? 0), 0); return <section key={category} className="border-b last:border-b-0"><div className="flex items-center justify-between bg-muted/40 px-4 py-2.5"><span className="text-[.68rem] font-semibold uppercase tracking-[.08em] text-muted-foreground">{category === "stocks" ? "Stocks" : "Cash"}</span><span className={`font-mono text-xs ${changeClass(subtotal)}`}>{formatSigned(subtotal, true)}</span></div><div className="divide-y">{items.map((item) => <div className="grid grid-cols-[minmax(7rem,1fr)_minmax(6rem,1.4fr)_auto] items-center gap-3 px-4 py-3 text-sm" key={item.account}><span className="truncate font-medium">{item.label}</span><div className="h-1.5 overflow-hidden rounded-full bg-muted"><div className={`h-full rounded-full ${item.change !== undefined && item.change < 0 ? "bg-rose-400" : "bg-emerald-400"}`} style={{ width: `${Math.abs(item.change ?? 0) / maxChange * 100}%` }} /></div><span className={changeClass(item.change)}>{formatSigned(item.change, true)}</span></div>)}</div></section>; })}</CardContent></Card>
    </section>
    <Alert role="note"><AlertTitle>How to read these trends</AlertTitle><AlertDescription>Momentum compares the latest three-month average with the previous three months. Drawdown compares the current balance with the selected-range high. Tracked totals can include carried balances; changes include deposits, withdrawals, and market movement, so they are not investment returns.</AlertDescription></Alert>
    <section className="grid items-start gap-3 lg:grid-cols-3" aria-label="Trend statistics">
      <Card><CardHeader className="border-b"><CardTitle>Year-over-year</CardTitle><CardDescription>{trends.yearOverYear ? `Compared with ${trends.yearOverYear.comparisonDate}` : "A matching prior-year month is required"}</CardDescription></CardHeader><CardContent className="divide-y p-0"><TrendRow label="Total" change={trends.yearOverYear?.total} /><TrendRow label="Cash" change={trends.yearOverYear?.money} /><TrendRow label="Stocks" change={trends.yearOverYear?.stocks} /></CardContent></Card>
      <Card><CardHeader className="border-b"><CardTitle>Selected-range trend</CardTitle><CardDescription>Calculated from the visible snapshots</CardDescription></CardHeader><CardContent className="divide-y p-0"><TrendRow label="Cumulative change" change={trends.periodChange} /><StatRow label="Geometric monthly change" value={formatTrendPercent(trends.geometricAverageMonthlyPercent)} /><StatRow label="Average total change" value={formatSigned(trends.averageMonthlyChange, true)} /><StatRow label="Average cash change" value={formatSigned(trends.averageMoneyChange, true)} /><StatRow label="Average stock change" value={formatSigned(trends.averageStocksChange, true)} /><StatRow label="High-water mark" value={trends.highWaterMark ? preciseCurrency.format(trends.highWaterMark.value) : "—"} detail={trends.highWaterMark?.date} /></CardContent></Card>
      <Card><CardHeader className="border-b"><CardTitle>Annual change and allocation</CardTitle><CardDescription>Each year starts from the prior year-end when available</CardDescription></CardHeader><CardContent className="divide-y p-0">{trends.yearlyChanges.map((item) => <TrendRow key={item.year} label={String(item.year)} change={item} />)}{trends.allocation?.previousYear ? <AllocationRow label={trends.allocation.previousYear.date} money={trends.allocation.previousYear.money} stocks={trends.allocation.previousYear.stocks} /> : null}{trends.allocation ? <AllocationRow label="Current" money={trends.allocation.current.money} stocks={trends.allocation.current.stocks} /> : null}<div className="px-4 py-3 text-xs text-muted-foreground">Balance movement includes transfers, deposits, withdrawals, and market changes. It is not an investment-return calculation.</div></CardContent></Card>
    </section>
  </>;
}

function Accounts({ accounts, accountLabels, accountRoles, accountLastObserved, months, latest, previous }: { accounts: string[]; accountLabels: Record<string, string>; accountRoles: Record<string, "cash" | "investment">; accountLastObserved: Record<string, string>; months: GroupedMonth[]; latest?: GroupedMonth; previous?: GroupedMonth }) {
  const [query, setQuery] = useState("");
  const [scope, setScope] = useState<"all" | "cash" | "investment">("all");
  const [sort, setSort] = useState<MoneySort<AccountSortKey>>({ key: "value", direction: "desc" });
  const first = months.at(0);
  const cashAccounts = accounts.filter((account) => roleCategory(accountRoles, account) === "money");
  const investmentAccounts = accounts.filter((account) => roleCategory(accountRoles, account) === "stocks");
  const chartCashAccounts = cashAccounts.filter((account) => accountLastObserved[account] !== undefined);
  const chartInvestmentAccounts = investmentAccounts.filter((account) => accountLastObserved[account] !== undefined);
  const snapshotAccounts = accounts.filter((account) => accountLastObserved[account] !== undefined);
  const rows = accountRows(accounts, accountLabels, latest, previous).map((row) => {
    const firstValue = first?.values[row.account];
    const comparable = first?.observedAccounts.includes(row.account) && latest?.observedAccounts.includes(row.account);
    const periodChange = comparable && row.value !== undefined && firstValue !== undefined ? row.value - firstValue : undefined;
    const range = rangeValuesForAccount(months, row.account);
    return { ...row, category: accountRoles[row.account] === "investment" ? "Investment" : "Cash", firstValue, periodChange,
      latestPercent: percent(row.change, row.previous), periodPercent: percent(periodChange, firstValue), share: latest?.total && row.value !== undefined ? row.value / latest.total * 100 : undefined,
      lastObserved: accountLastObserved[row.account], rangeMin: range?.minimum, rangeMax: range?.maximum };
  });
  const normalizedQuery = query.trim().toLocaleLowerCase("en-GB");
  const visibleRows = rows.filter((row) => (scope === "all" || accountRoles[row.account] === scope)
    && (!normalizedQuery || row.label.toLocaleLowerCase("en-GB").includes(normalizedQuery)))
    .sort((left, right) => compareAccountRows(left, right, sort));
  const observedCount = latest ? accounts.filter((account) => latest.observedAccounts.includes(account)).length : 0;
  const changeSort = (key: AccountSortKey) => setSort((current) => nextMoneySort(current, key, ["label", "category", "lastObserved"]));
  return <>
    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4" aria-label="Account summary"><Metric label="Tracked total" value={latest ? currency.format(latest.total) : "No data"} detail={latest?.date} /><Metric label="Cash" value={latest ? currency.format(latest.money) : "—"} detail={`${cashAccounts.length} accounts`} /><Metric label="Investments" value={latest ? currency.format(latest.stocks) : "—"} detail={`${investmentAccounts.length} accounts`} /><Metric label="Balances observed" value={`${observedCount} / ${snapshotAccounts.length}`} detail={`${accounts.length - snapshotAccounts.length} accounts without snapshots`} /></section>
    <section className={`grid items-start gap-3 ${chartInvestmentAccounts.length ? "xl:grid-cols-2" : ""}`} aria-label="Balance history">
      <AccountGroupChart title="Cash history" category="money" accounts={chartCashAccounts} accountLabels={accountLabels} months={months} first={first} latest={latest} />
      {chartInvestmentAccounts.length ? <AccountGroupChart title="Investment balance history" category="stocks" accounts={chartInvestmentAccounts} accountLabels={accountLabels} months={months} first={first} latest={latest} /> : null}
    </section>
    <Card><CardHeader className="gap-4 border-b"><div><CardTitle>Accounts</CardTitle><CardDescription>Filter and sort balances, movement, allocation, and freshness</CardDescription></div><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div className="flex w-fit rounded-lg bg-muted p-1" aria-label="Account type filter">{(["all", "cash", "investment"] as const).map((item) => <Button key={item} type="button" size="sm" variant={scope === item ? "secondary" : "ghost"} className="h-7 capitalize" aria-pressed={scope === item} onClick={() => setScope(item)}>{item === "all" ? `All ${accounts.length}` : `${item === "cash" ? "Cash" : "Investments"} ${item === "cash" ? cashAccounts.length : investmentAccounts.length}`}</Button>)}</div><MoneyTableSearch value={query} onValue={setQuery} placeholder="Filter accounts…" /></div></CardHeader><CardContent className="overflow-x-auto p-0 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring" tabIndex={0} role="region" aria-label="Account detail table"><table className="w-full min-w-[68rem] text-sm"><caption className="sr-only">Balances, changes, allocation and observation dates by account</caption><thead className="border-b text-xs text-muted-foreground"><tr><MoneySortableHead label="Account" sortKey="label" active={sort} onSort={changeSort} /><MoneySortableHead label="Category" sortKey="category" active={sort} onSort={changeSort} /><MoneySortableHead label="Balance" sortKey="value" active={sort} onSort={changeSort} align="right" /><MoneySortableHead label="Latest" sortKey="change" active={sort} onSort={changeSort} align="right" /><MoneySortableHead label="Latest %" sortKey="latestPercent" active={sort} onSort={changeSort} align="right" /><MoneySortableHead label="Selected period" sortKey="periodChange" active={sort} onSort={changeSort} align="right" /><MoneySortableHead label="Period %" sortKey="periodPercent" active={sort} onSort={changeSort} align="right" /><MoneySortableHead label="Share" sortKey="share" active={sort} onSort={changeSort} align="right" /><MoneySortableHead label="Last observed" sortKey="lastObserved" active={sort} onSort={changeSort} align="right" /><MoneySortableHead label="Tracked range" sortKey="rangeMax" active={sort} onSort={changeSort} align="right" /></tr></thead><tbody className="divide-y">{visibleRows.map((row) => <tr className="transition-colors hover:bg-muted/40" key={row.account}><td className="px-4 py-3 font-medium">{row.label}</td><td className="px-4 py-3"><Badge variant="outline">{row.category}</Badge></td><td className="px-4 py-3 text-right font-mono">{row.value === undefined ? <span className="text-muted-foreground">—</span> : preciseCurrency.format(row.value)}</td><td className={`px-4 py-3 text-right font-mono ${changeClass(row.change)}`}>{formatSigned(row.change, true)}</td><td className={`px-4 py-3 text-right font-mono ${changeClass(row.change)}`}>{formatTrendPercent(row.latestPercent)}</td><td className={`px-4 py-3 text-right font-mono ${changeClass(row.periodChange)}`}>{formatSigned(row.periodChange, true)}</td><td className={`px-4 py-3 text-right font-mono ${changeClass(row.periodChange)}`}>{formatTrendPercent(row.periodPercent)}</td><td className="px-4 py-3 text-right font-mono">{row.share === undefined ? "—" : `${row.share.toFixed(1)}%`}</td><td className="px-4 py-3 text-right font-mono text-xs text-muted-foreground">{row.lastObserved ?? "No snapshot"}</td><td className="px-4 py-3 text-right font-mono text-xs text-muted-foreground">{row.rangeMin === undefined || row.rangeMax === undefined ? "—" : `${currency.format(row.rangeMin)} – ${currency.format(row.rangeMax)}`}</td></tr>)}{visibleRows.length === 0 ? <tr><td className="px-4 py-10 text-center text-muted-foreground" colSpan={10}>No accounts match this filter.</td></tr> : null}</tbody></table></CardContent></Card>
  </>;
}

type AccountSortKey = "label" | "category" | "value" | "change" | "latestPercent" | "periodChange" | "periodPercent" | "share" | "lastObserved" | "rangeMax";
type HistorySortKey = "date" | "total" | "change" | "money" | "stocks" | "coverage" | `account:${string}`;
function compareAccountRows<Row extends { label: string } & Record<AccountSortKey, string | number | undefined>>(left: Row, right: Row, sort: MoneySort<AccountSortKey>) {
  const a = left[sort.key]; const b = right[sort.key];
  return compareMoneyValues(a, b, sort.direction) || left.label.localeCompare(right.label);
}

function AccountGroupChart({ title, category, accounts, accountLabels, months, first, latest }: { title: string; category: MoneyTrackerAccountCategory; accounts: string[]; accountLabels: Record<string, string>; months: GroupedMonth[]; first?: GroupedMonth; latest?: GroupedMonth }) {
  const dataKey = category === "money" ? "money" : "stocks";
  const label = category === "money" ? "Cash" : "Stocks";
  const palette = category === "money" ? ["#67e8f9", "#60a5fa", "#34d399", "#facc15", "#fb923c"] : ["#c084fc", "#f472b6", "#a78bfa"];
  const config = { ...Object.fromEntries(accounts.map((account) => [account, { label: accountLabels[account] ?? account }])), [dataKey]: { label: `${label} total` } } satisfies ChartConfig;
  const startValue = first?.[dataKey];
  const latestValue = latest?.[dataKey];
  const comparable = accounts.length > 0 && accounts.every((account) => first?.observedAccounts.includes(account) && latest?.observedAccounts.includes(account));
  const periodChange = comparable && startValue !== undefined && latestValue !== undefined ? latestValue - startValue : undefined;
  return <ChartCard title={title} description={`${latestValue === undefined ? "No data" : preciseCurrency.format(latestValue)} latest tracked · ${formatSigned(periodChange, true)} in the selected period`}><MountedChart fallback={<ChartFallback values={months.map((month) => month[dataKey])} />}><ChartContainer config={config} className="h-72 w-full aspect-auto" role="img" aria-label={`${label} balances by account over the selected period. Exact values follow in an expandable table.`}><ComposedChart accessibilityLayer={false} data={months}><CartesianGrid vertical={false} /><XAxis dataKey="date" tickLine={false} axisLine={false} minTickGap={24} /><YAxis tickLine={false} axisLine={false} width={68} tickFormatter={(value: number) => currency.format(value)} /><ChartTooltip content={<ChartTooltipContent />} />{accounts.map((account, index) => <Area key={account} dataKey={`values.${account}`} name={accountLabels[account] ?? account} type="monotone" stackId={dataKey} fill={palette[index % palette.length]} fillOpacity={0.62} stroke={palette[index % palette.length]} strokeWidth={1.5} />)}<Line dataKey={dataKey} name={`${label} total`} type="monotone" stroke="#fafafa" strokeWidth={2} dot={false} /></ComposedChart></ChartContainer></MountedChart><AccountDataDisclosure months={months} accounts={accounts} accountLabels={accountLabels} totalKey={dataKey} totalLabel={`${label} total`} /></ChartCard>;
}

export function History({ accounts, accountLabels, months }: { accounts: string[]; accountLabels: Record<string, string>; months: GroupedMonth[] }) {
  const [sort, setSort] = useState<MoneySort<HistorySortKey>>({ key: "date", direction: "desc" });
  const changes = withObservedChanges(months, accounts.length);
  const latest = months.at(-1);
  const previous = months.at(-2);
  const latestObservedChange = changes.at(-1);
  const latestChange = latestObservedChange && latestObservedChange.date === latest?.date ? latestObservedChange.change : undefined;
  const complete = months.filter((month) => month.observedAccounts.length === accounts.length).length;
  const largestIncrease = changes.length ? changes.reduce((best, item) => item.change > best.change ? item : best) : undefined;
  const largestDecrease = changes.length ? changes.reduce((best, item) => item.change < best.change ? item : best) : undefined;
  const fullyObserved = months.filter((month) => isFullyObserved(month, accounts.length));
  const high = fullyObserved.length ? fullyObserved.reduce((best, item) => item.total > best.total ? item : best) : undefined;
  const low = fullyObserved.length ? fullyObserved.reduce((best, item) => item.total < best.total ? item : best) : undefined;
  const historyRows = months.map((month, index) => { const older = months[index - 1]; return { month, change: older && isFullyObserved(month, accounts.length) && isFullyObserved(older, accounts.length) ? month.total - older.total : undefined, carried: accounts.length - month.observedAccounts.length }; }).sort((left, right) => {
    const value = (row: typeof left) => sort.key === "date" ? row.month.date : sort.key === "total" ? row.month.total : sort.key === "change" ? row.change : sort.key === "money" ? row.month.money : sort.key === "stocks" ? row.month.stocks : sort.key === "coverage" ? row.carried : row.month.values[sort.key.slice("account:".length)];
    return compareMoneyValues(value(left), value(right), sort.direction) || right.month.date.localeCompare(left.month.date);
  });
  const changeSort = (key: HistorySortKey) => setSort((current) => nextMoneySort(current, key, ["date"]));
  return <>
    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4" aria-label="History summary"><Metric label="Snapshots shown" value={String(months.length)} detail={months.length ? `${months[0]!.date} to ${months.at(-1)!.date}` : undefined} /><Metric label="Latest tracked total" value={latest ? currency.format(latest.total) : "No data"} detail={latest ? `${latest.date} · ${accounts.length - latest.observedAccounts.length} carried` : undefined} /><Metric label="Latest change" value={formatSigned(latestChange)} detail={latestChange !== undefined && latest && previous ? `${previous.date} to ${latest.date}` : "requires both months fully observed"} tone={tone(latestChange)} /><Metric label="Fully observed months" value={`${complete} / ${months.length}`} detail="every account observed in month" /></section>
    <Card><CardHeader className="border-b"><CardTitle>Monthly snapshot ledger</CardTitle><CardDescription>Click a header to sort. Values not observed in a month are carried forward from their last observation.</CardDescription></CardHeader><CardContent className="overflow-x-auto p-0 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring" tabIndex={0} role="region" aria-label="Monthly balance snapshot table"><table className="w-full min-w-max text-sm"><caption className="sr-only">Monthly balances with observation coverage</caption><thead className="border-b text-xs text-muted-foreground"><tr><MoneySortableHead label="Date" sortKey="date" active={sort} onSort={changeSort} className="sticky left-0 z-10 bg-card" /><MoneySortableHead label="Tracked total" sortKey="total" active={sort} onSort={changeSort} align="right" /><MoneySortableHead label="Change" sortKey="change" active={sort} onSort={changeSort} align="right" /><MoneySortableHead label="Cash" sortKey="money" active={sort} onSort={changeSort} align="right" /><MoneySortableHead label="Investments" sortKey="stocks" active={sort} onSort={changeSort} align="right" />{accounts.map((account) => <MoneySortableHead label={accountLabels[account] ?? account} sortKey={`account:${account}`} active={sort} onSort={changeSort} align="right" key={account} />)}<MoneySortableHead label="Coverage" sortKey="coverage" active={sort} onSort={changeSort} align="right" /></tr></thead><tbody className="divide-y">{historyRows.map(({ month, change, carried }) => <tr className="hover:bg-muted/30" key={month.date}><td className="sticky left-0 bg-card px-4 py-3 font-medium">{month.date}</td><td className="px-4 py-3 text-right font-mono font-medium">{preciseCurrency.format(month.total)}</td><td className={`px-4 py-3 text-right font-mono ${changeClass(change)}`}>{formatSigned(change, true)}</td><td className="px-4 py-3 text-right font-mono">{preciseCurrency.format(month.money)}</td><td className="px-4 py-3 text-right font-mono">{preciseCurrency.format(month.stocks)}</td>{accounts.map((account) => <td className="px-4 py-3 text-right font-mono" key={account}>{month.values[account] === undefined ? <span className="text-muted-foreground">—</span> : preciseCurrency.format(month.values[account])}</td>)}<td className="px-4 py-3 text-right"><Badge variant={carried === 0 ? "outline" : "destructive"}>{carried === 0 ? "Observed" : `${carried} carried`}</Badge></td></tr>)}</tbody></table></CardContent></Card>
    <section className="grid items-start gap-3 lg:grid-cols-2">
      <Card><CardHeader className="border-b"><CardTitle>Selected-period extremes</CardTitle><CardDescription>Largest balance movements and observed range</CardDescription></CardHeader><CardContent className="divide-y p-0"><StatRow label="Largest increase" value={formatSigned(largestIncrease?.change, true)} detail={largestIncrease?.date} /><StatRow label="Largest decrease" value={formatSigned(largestDecrease?.change, true)} detail={largestDecrease?.date} /><StatRow label="Highest balance" value={high ? preciseCurrency.format(high.total) : "—"} detail={high?.date} /><StatRow label="Lowest balance" value={low ? preciseCurrency.format(low.total) : "—"} detail={low?.date} /></CardContent></Card>
      <Card><CardHeader className="border-b"><CardTitle>Data contract</CardTitle><CardDescription>What these analytics can assert</CardDescription></CardHeader><CardContent className="space-y-3 pt-5 text-sm"><p><strong>{accounts.length}</strong> tracked accounts across <strong>{months.length}</strong> monthly snapshots.</p><p><strong>Cash and investments</strong> use the persisted account role, never the account label.</p><p className="text-muted-foreground">Missing monthly observations are carried forward and labeled as such. Balance changes are not investment returns: deposits, withdrawals, and market performance cannot be separated from snapshots alone.</p><Alert><AlertTitle>Money-owned history</AlertTitle><AlertDescription>Imported running balances and manual snapshots are stored in the private Money ledger.</AlertDescription></Alert></CardContent></Card>
    </section>
  </>;
}

function BalanceChart({ months, period, onPeriod }: { months: GroupedMonth[]; period: Period; onPeriod: (period: Period) => void }) {
  return <Card><CardHeader className="border-b"><div className="flex flex-wrap items-start justify-between gap-3"><div><CardTitle>Tracked net worth</CardTitle><CardDescription>Actual monthly total, composed from cash and reported investment balances</CardDescription></div><PeriodSelector period={period} onPeriod={onPeriod} /></div></CardHeader><CardContent className="pt-5"><MountedChart fallback={<ChartFallback values={months.map((month) => month.total)} />}><ChartContainer config={totalConfig} className="h-[23rem] w-full aspect-auto" initialDimension={{ width: 760, height: 368 }} role="img" aria-label="Tracked total over time, composed from cash and reported investment balances. Exact values follow in an expandable table."><ComposedChart accessibilityLayer={false} data={months} margin={{ left: 4, right: 12, top: 8 }}><defs><linearGradient id="money-overview-cash" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor={colors[0]} stopOpacity={0.34} /><stop offset="95%" stopColor={colors[0]} stopOpacity={0.04} /></linearGradient><linearGradient id="money-overview-stocks" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor={colors[1]} stopOpacity={0.34} /><stop offset="95%" stopColor={colors[1]} stopOpacity={0.04} /></linearGradient></defs><CartesianGrid vertical={false} /><XAxis dataKey="date" tickLine={false} axisLine={false} tickMargin={10} minTickGap={28} /><YAxis tickLine={false} axisLine={false} width={72} tickFormatter={(value: number) => currency.format(value)} /><ChartTooltip content={<ChartTooltipContent />} /><Area dataKey="money" name="Cash" type="monotone" stackId="tracked" fill="url(#money-overview-cash)" stroke={colors[0]} strokeWidth={1.5} /><Area dataKey="stocks" name="Investment balances" type="monotone" stackId="tracked" fill="url(#money-overview-stocks)" stroke={colors[1]} strokeWidth={1.5} /><Line dataKey="total" name="Tracked total" type="monotone" stroke="#fafafa" strokeWidth={2.5} dot={false} /></ComposedChart></ChartContainer></MountedChart><BalanceDataDisclosure months={months} /></CardContent></Card>;
}

function AttentionRow({ label, value, detail, ready, view, action }: { label: string; value: string; detail: string; ready: boolean; view: Exclude<MoneyTrackerView, "overview">; action: string }) {
  const content = <><div><p className="text-sm font-medium">{label}</p><p className="mt-0.5 text-xs text-muted-foreground">{ready ? detail : `${detail} · ${action}`}</p></div><Badge variant={ready ? "outline" : "destructive"}>{value}</Badge></>;
  return ready ? <div className="grid grid-cols-[minmax(0,1fr)_auto] gap-3 px-4 py-3">{content}</div> : <Link to="/money" search={{ view }} className="grid grid-cols-[minmax(0,1fr)_auto] gap-3 px-4 py-3 hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring">{content}</Link>;
}

function CashFlowBar({ label, value, maximum, tone: barTone }: { label: string; value: number; maximum: number; tone: "income" | "spend" }) {
  return <div className="min-w-0"><div className="mb-1 flex justify-between gap-2"><span className="text-muted-foreground">{label}</span><span className="font-mono">{formatMinor(value, "EUR")}</span></div><div className="h-1.5 overflow-hidden rounded-full bg-muted"><div className={barTone === "income" ? "h-full rounded-full bg-emerald-400" : "h-full rounded-full bg-cyan-300"} style={{ width: `${value / maximum * 100}%` }} /></div></div>;
}

function viewDescription(view: MoneyTrackerView) {
  return view === "overview" ? "Your tracked financial position, recent cash flow, freshness, and open review work." : view === "cash-flow" ? "Income, spending, and imported monthly cash-flow activity." : view === "transactions" ? "The normalized ledger with complete search, classification, and transfer review." : view === "investments" ? "Current EUR valuation, historical closes, FIFO performance, and imported activity." : view === "accounts" ? "Cash balances, observation freshness, concentration, and monthly history." : view === "categories" ? "Explore spending by category, month, merchant, and underlying transaction." : view === "insights" ? "Balance momentum, concentration, drawdown, trends, and a conservative run-rate scenario." : "Imports, reconciliation, coverage, rules, and analytical limits.";
}
function PeriodSelector({ period, onPeriod }: { period: Period; onPeriod: (period: Period) => void }) { return <div role="group" aria-label="Balance range" className="flex gap-1"><PeriodButton active={period === "6m"} onClick={() => onPeriod("6m")}>6M</PeriodButton><PeriodButton active={period === "1y"} onClick={() => onPeriod("1y")}>1Y</PeriodButton><PeriodButton active={period === "all"} onClick={() => onPeriod("all")}>All</PeriodButton></div>; }
function PeriodButton({ active, onClick, children }: { active: boolean; onClick: () => void; children: React.ReactNode }) { return <Button type="button" size="sm" variant={active ? "default" : "outline"} aria-pressed={active} onClick={onClick}>{children}</Button>; }
function ChartCard({ title, description, children }: { title: string; description: string; children: React.ReactNode }) { return <Card><CardHeader className="border-b"><CardTitle>{title}</CardTitle><CardDescription>{description}</CardDescription></CardHeader><CardContent className="pt-5">{children}</CardContent></Card>; }
function MountedChart({ fallback, children }: { fallback: React.ReactNode; children: React.ReactNode }) { const [mounted, setMounted] = useState(false); useEffect(() => setMounted(true), []); return mounted ? children : fallback; }
function ChartFallback({ values }: { values: number[] }) { const latest = values.at(-1); return <div className="grid h-64 place-items-center rounded-md border border-dashed bg-muted/40 text-center"><div><p className="text-sm font-medium">Chart loading</p><p className="mt-1 text-xs text-muted-foreground">{latest === undefined ? "No chart data" : `Latest value ${currency.format(latest)}`}</p></div></div>; }
function BalanceDataDisclosure({ months, includeTrend = false }: { months: GroupedMonth[]; includeTrend?: boolean }) { return <ChartDataDetails label="View balance chart data"><table className="w-full min-w-[34rem] text-xs"><caption className="sr-only">Exact values plotted in the balance chart</caption><thead className="border-b text-muted-foreground"><tr><th className="px-3 py-2 text-left">Month</th><th className="px-3 py-2 text-right">Cash</th><th className="px-3 py-2 text-right">Investments</th><th className="px-3 py-2 text-right">Tracked total</th>{includeTrend ? <th className="px-3 py-2 text-right">Linear trend</th> : null}</tr></thead><tbody className="divide-y">{months.map((month) => <tr key={month.date}><td className="px-3 py-2">{month.date}</td><td className="px-3 py-2 text-right font-mono">{preciseCurrency.format(month.money)}</td><td className="px-3 py-2 text-right font-mono">{preciseCurrency.format(month.stocks)}</td><td className="px-3 py-2 text-right font-mono">{preciseCurrency.format(month.total)}</td>{includeTrend ? <td className="px-3 py-2 text-right font-mono">{preciseCurrency.format(month.trend)}</td> : null}</tr>)}</tbody></table></ChartDataDetails>; }
function ChangeDataDisclosure({ changes }: { changes: Array<Month & { change: number }> }) { return <ChartDataDetails label="View monthly change data"><table className="w-full text-xs"><caption className="sr-only">Exact values plotted in the monthly balance change chart</caption><thead className="border-b text-muted-foreground"><tr><th className="px-3 py-2 text-left">Month</th><th className="px-3 py-2 text-right">Change</th></tr></thead><tbody className="divide-y">{changes.map((month) => <tr key={month.date}><td className="px-3 py-2">{month.date}</td><td className="px-3 py-2 text-right font-mono">{formatSigned(month.change, true)}</td></tr>)}</tbody></table></ChartDataDetails>; }
function AccountDataDisclosure({ months, accounts, accountLabels, totalKey, totalLabel }: { months: GroupedMonth[]; accounts: string[]; accountLabels: Record<string, string>; totalKey: "money" | "stocks"; totalLabel: string }) { return <ChartDataDetails label="View account chart data"><table className="w-full min-w-max text-xs"><caption className="sr-only">Exact values plotted in the account history chart</caption><thead className="border-b text-muted-foreground"><tr><th className="px-3 py-2 text-left">Month</th>{accounts.map((account) => <th className="px-3 py-2 text-right" key={account}>{accountLabels[account] ?? account}</th>)}<th className="px-3 py-2 text-right">{totalLabel}</th></tr></thead><tbody className="divide-y">{months.map((month) => <tr key={month.date}><td className="px-3 py-2">{month.date}</td>{accounts.map((account) => <td className="px-3 py-2 text-right font-mono" key={account}>{month.values[account] === undefined ? "—" : preciseCurrency.format(month.values[account])}</td>)}<td className="px-3 py-2 text-right font-mono">{preciseCurrency.format(month[totalKey])}</td></tr>)}</tbody></table></ChartDataDetails>; }
function ChartDataDetails({ label, children }: { label: string; children: React.ReactNode }) { return <details className="mt-3 border-t pt-3"><summary className="w-fit cursor-pointer rounded-sm text-xs font-medium text-muted-foreground hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">{label}</summary><div className="mt-3 overflow-x-auto rounded-md border focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring" tabIndex={0} role="region" aria-label={label}>{children}</div></details>; }
function Metric({ label, value, detail, tone: valueTone }: { label: string; value: string; detail?: string; tone?: "positive" | "negative" }) { return <Card><CardContent className="min-w-0 p-4"><p className="text-[.68rem] font-semibold uppercase tracking-[.08em] text-muted-foreground">{label}</p><strong className="mt-1.5 block break-words text-[clamp(1.25rem,2vw,1.5rem)] tracking-tight">{value}</strong>{detail ? <span className={valueTone === "negative" ? "mt-1 block text-xs text-rose-400" : valueTone === "positive" ? "mt-1 block text-xs text-emerald-400" : "mt-1 block text-xs text-muted-foreground"}>{detail}</span> : null}</CardContent></Card>; }
function StatRow({ label, value, detail }: { label: string; value: string; detail?: string }) { return <div className="flex items-center justify-between gap-4 px-4 py-3 text-sm"><span className="text-muted-foreground">{label}</span><span className="text-right font-mono"><strong className="font-medium text-foreground">{value}</strong>{detail ? <span className="ml-2 text-xs text-muted-foreground">{detail}</span> : null}</span></div>; }
function TrendRow({ label, change }: { label: string; change?: { change: number; percent?: number } }) { return <div className="flex items-center justify-between gap-4 px-4 py-3 text-sm"><span className="text-muted-foreground">{label}</span><span className={`text-right font-mono ${changeClass(change?.change)}`}><strong className="font-medium">{formatSigned(change?.change, true)}</strong><span className="ml-2 text-xs">{formatTrendPercent(change?.percent)}</span></span></div>; }
function AllocationRow({ label, money, stocks }: { label: string; money: number; stocks: number }) { return <div className="space-y-2 px-4 py-3"><div className="flex items-center justify-between text-xs"><span className="text-muted-foreground">{label}</span><span className="font-mono"><span className="text-cyan-300">Cash {money.toFixed(1)}%</span><span className="ml-3 text-purple-300">Stocks {stocks.toFixed(1)}%</span></span></div><div className="flex h-1.5 overflow-hidden rounded-full bg-muted"><div className="bg-cyan-300" style={{ width: `${money}%` }} /><div className="bg-purple-400" style={{ width: `${stocks}%` }} /></div></div>; }
function TooltipValue({ label, value }: { label: string; value: string }) { return <div className="flex min-w-40 items-center justify-between gap-4"><span className="text-muted-foreground">{label}</span><strong>{value}</strong></div>; }
function withChanges(months: Month[]) { return months.slice(1).map((month, index) => ({ ...month, change: month.total - months[index]!.total })); }
function withObservedChanges(months: Month[], accountCount: number) { return months.slice(1).flatMap((month, index) => { const previous = months[index]!; return isFullyObserved(month, accountCount) && isFullyObserved(previous, accountCount) ? [{ ...month, change: month.total - previous.total }] : []; }); }
function accountRows(accounts: string[], labels: Record<string, string>, latest?: Month, previous?: Month) { return accounts.map((account) => { const value = latest?.values[account]; const oldValue = previous?.values[account]; const comparable = latest?.observedAccounts.includes(account) && previous?.observedAccounts.includes(account); return { account, label: labels[account] ?? account, value, previous: oldValue, change: comparable && value !== undefined && oldValue !== undefined ? value - oldValue : undefined }; }); }
function isFullyObserved(month: Month & { observed?: boolean }, accountCount: number) { return month.observed ?? (accountCount > 0 && month.observedAccounts.length === accountCount); }
function formatActivityDate(value: string) { return new Intl.DateTimeFormat("en-GB", { dateStyle: "medium", timeZone: "Europe/Berlin" }).format(new Date(value)); }
function formatMinor(value: number, valueCurrency: string) { return new Intl.NumberFormat("de-DE", { style: "currency", currency: valueCurrency }).format(value / 100); }
function formatSigned(value?: number, precise = false) { if (value === undefined) return "—"; return `${value >= 0 ? "+" : ""}${(precise ? preciseCurrency : currency).format(value)}`; }
function formatPercent(change?: number, base?: number) { return change === undefined || !base ? "—" : `${change >= 0 ? "+" : ""}${(change / base * 100).toFixed(1)}%`; }
function formatTrendPercent(value?: number) { return value === undefined ? "—" : `${value >= 0 ? "+" : ""}${value.toFixed(1)}%`; }
function formatPoints(value: number) { return `${value >= 0 ? "+" : ""}${value.toFixed(1)} pp`; }
function tone(value?: number): "positive" | "negative" | undefined { return value === undefined ? undefined : value < 0 ? "negative" : "positive"; }
function changeClass(value?: number) { return value === undefined ? "text-muted-foreground" : value < 0 ? "text-rose-400" : "text-emerald-400"; }
function rangeValuesForAccount(months: Month[], account: string) { const values = months.map((month) => month.values[account]).filter((value): value is number => value !== undefined); return values.length ? { minimum: Math.min(...values), maximum: Math.max(...values) } : undefined; }
function percent(change?: number, base?: number) { return change === undefined || !base ? undefined : change / base * 100; }
export function groupMonth(month: Month, roles: Record<string, "cash" | "investment">): GroupedMonth { let money = 0; let stocks = 0; for (const [account, value] of Object.entries(month.values)) { if (roleCategory(roles, account) === "stocks") stocks += value; else money += value; } return { ...month, money, stocks, trend: month.total }; }
function cashMonth(month: Month, cashAccounts: readonly string[]): GroupedMonth {
  const values = Object.fromEntries(cashAccounts.flatMap((account) => month.values[account] === undefined ? [] : [[account, month.values[account]]])) as Record<string, number>;
  const observedAccounts = month.observedAccounts.filter((account) => cashAccounts.includes(account));
  const money = Object.values(values).reduce((sum, value) => sum + value, 0);
  return { ...month, values, observedAccounts, total: money, money, stocks: 0, trend: money };
}
function cashCoverage(month: Month | undefined, cashAccounts: readonly string[]) {
  const tracked = cashAccounts.filter((account) => month?.observedAccounts.includes(account) || (month?.values[account] ?? 0) !== 0);
  return { observedCashAccountCount: tracked.filter((account) => month?.observedAccounts.includes(account)).length, cashAccountCount: tracked.length };
}
function roleCategory(roles: Record<string, "cash" | "investment">, account: string): MoneyTrackerAccountCategory { return roles[account] === "investment" ? "stocks" : "money"; }
function withLinearTrend(months: GroupedMonth[]) {
  if (months.length < 2) return months;
  const meanX = (months.length - 1) / 2;
  const meanY = months.reduce((sum, month) => sum + month.total, 0) / months.length;
  const slopeNumerator = months.reduce((sum, month, index) => sum + (index - meanX) * (month.total - meanY), 0);
  const slopeDenominator = months.reduce((sum, _month, index) => sum + (index - meanX) ** 2, 0);
  const slope = slopeNumerator / slopeDenominator;
  return months.map((month, index) => ({ ...month, trend: meanY + slope * (index - meanX) }));
}
